  "diff": "diff --git a/routes_reports.py b/routes_reports.py\nindex 0168031..f5cafbe 100644\n--- a/routes_reports.py\n+++ b/routes_reports.py\n@@ -19,3 +19,14 @@ def takings(day: str):\n     if day == \"today\":\n         day = today()\n     return services.takings_on(day)\n+\n+\n+@router.get(\"/api/reports/workload/{day}\")\n+def workload(day: str):\n+    \"\"\"Mechanic workload for the shop week (Mon-Sat) containing a day. day is YYYY-MM-DD, or the word 'today';\n+    a Sunday means the Mon-Sat week just gone. Returns {ok, week_start, week_end, mechanics: [{mechanic_id, name,\n+    weekly_capacity_hours, workload_hours, spare_hours, overloaded, job_count}]}, most overloaded first.\n+    Workload is the estimated hours of jobs due that week that aren't ready or collected yet.\"\"\"\n+    if day == \"today\":\n+        day = today()\n+    return services.mechanic_workload(day)\ndiff --git a/services.py b/services.py\nindex b50fa41..066506f 100644\n--- a/services.py\n+++ b/services.py\n@@ -360,3 +360,37 @@ def week_bounds(day=None):\n     monday = date.fromordinal(d.toordinal() - d.weekday())\n     saturday = date.fromordinal(monday.toordinal() + 5)\n     return monday.isoformat(), saturday.isoformat()\n+\n+\n+def mechanic_workload(day):\n+    \"\"\"Each mechanic's workload for the shop week (Mon-Sat) containing `day` (YYYY-MM-DD).\n+\n+    A Sunday counts as the end of the Mon-Sat week just gone. Workload = hours of their jobs due\n+    that week that aren't 'ready' or 'collected' yet.\n+\n+    Returns {ok: True, week_start, week_end, mechanics: [{mechanic_id, name, weekly_capacity_hours,\n+    workload_hours, spare_hours, overloaded, job_count}]} sorted by spare_hours, most overloaded first\n+    (every mechanic is listed, even with no jobs), or {ok: False, error} if the date isn't valid.\n+    \"\"\"\n+    try:\n+        datetime.strptime(day, \"%Y-%m-%d\")\n+    except (TypeError, ValueError):\n+        return {\"ok\": False, \"error\": f\"'{day}' isn't a date. Use YYYY-MM-DD or 'today'\"}\n+    week_start, week_end = week_bounds(day)\n+    con = connect()\n+    rows = con.execute(\n+        \"\"\"SELECT m.id AS mechanic_id, m.name, m.weekly_capacity_hours,\n+                  coalesce(sum(j.estimate_hours), 0) AS workload_hours, count(j.id) AS job_count\n+           FROM mechanics m\n+           LEFT JOIN jobs j ON j.mechanic_id = m.id AND j.due_date BETWEEN ? AND ?\n+                           AND j.status NOT IN ('ready', 'collected')\n+           GROUP BY m.id ORDER BY m.id\"\"\",\n+        (week_start, week_end),\n+    ).fetchall()\n+    con.close()\n+    for r in rows:\n+        r[\"workload_hours\"] = round(r[\"workload_hours\"], 2)\n+        r[\"spare_hours\"] = round(r[\"weekly_capacity_hours\"] - r[\"workload_hours\"], 2)\n+        r[\"overloaded\"] = r[\"workload_hours\"] > r[\"weekly_capacity_hours\"]\n+    rows.sort(key=lambda r: r[\"spare_hours\"])\n+    return {\"ok\": True, \"week_start\": week_start, \"week_end\": week_end, \"mechanics\": rows}\ndiff --git a/tests/test_workload.py b/tests/test_workload.py\nnew file mode 100644\nindex 0000000..eb62311\n--- /dev/null\n+++ b/tests/test_workload.py\n@@ -0,0 +1,69 @@\n+# tests for GET /api/reports/workload/{day}. uses the throwaway database from conftest.py\n+# (\"today\" is Monday 2026-11-23, so this shop week is Mon 2026-11-23 to Sat 2026-11-28).\n+import db\n+\n+\n+def _set_jobs(client, jobs):\n+    \"\"\"Replace every job with our own: (mechanic name, hours, status, due_date).\"\"\"\n+    mech = {m[\"name\"]: m[\"id\"] for m in client.get(\"/api/mechanics\").json()}\n+    con = db.connect()\n+    con.execute(\"DELETE FROM job_parts\")\n+    con.execute(\"DELETE FROM invoices\")\n+    con.execute(\"DELETE FROM jobs\")\n+    for name, hours, status, due in jobs:\n+        con.execute(\n+            \"INSERT INTO jobs (customer_id, mechanic_id, work, estimate_hours, status, due_date, created) \"\n+            \"VALUES (1, ?, 'Service', ?, ?, ?, '2026-11-01 09:00:00')\",\n+            (mech[name], hours, status, due),\n+        )\n+    con.commit()\n+    con.close()\n+\n+\n+JOBS = [\n+    (\"Dev\", 8, \"booked\", \"2026-11-23\"),             # Monday: first day of the week, counts\n+    (\"Dev\", 15, \"in progress\", \"2026-11-28\"),       # Saturday: last day of the week, counts\n+    (\"Dev\", 5, \"booked\", \"2026-11-22\"),             # Sunday before: previous week\n+    (\"Dev\", 5, \"booked\", \"2026-11-29\"),             # Sunday after: not in this week\n+    (\"Ravi\", 2.5, \"waiting on parts\", \"2026-11-25\"),\n+    (\"Ravi\", 10, \"ready\", \"2026-11-25\"),            # ready: doesn't count\n+    (\"Ravi\", 10, \"collected\", \"2026-11-24\"),        # collected: doesn't count\n+    (\"Ravi\", 4, \"booked\", \"2026-11-21\"),            # Saturday of the previous week\n+]\n+\n+\n+def test_workload_week_and_exclusions(client):\n+    _set_jobs(client, JOBS)\n+    r = client.get(\"/api/reports/workload/2026-11-25\").json()\n+    assert r[\"ok\"] is True\n+    assert (r[\"week_start\"], r[\"week_end\"]) == (\"2026-11-23\", \"2026-11-28\")\n+    by_name = {m[\"name\"]: m for m in r[\"mechanics\"]}\n+    assert by_name[\"Dev\"] == {\"mechanic_id\": by_name[\"Dev\"][\"mechanic_id\"], \"name\": \"Dev\", \"weekly_capacity_hours\": 20,\n+                              \"workload_hours\": 23, \"spare_hours\": -3, \"overloaded\": True, \"job_count\": 2}\n+    assert by_name[\"Ravi\"][\"workload_hours\"] == 2.5 and by_name[\"Ravi\"][\"job_count\"] == 1\n+    assert by_name[\"Ravi\"][\"spare_hours\"] == 27.5 and by_name[\"Ravi\"][\"overloaded\"] is False\n+    # mechanics with nothing on are still listed\n+    assert by_name[\"Priya\"][\"workload_hours\"] == 0 and by_name[\"Priya\"][\"job_count\"] == 0\n+    assert by_name[\"Priya\"][\"spare_hours\"] == 30\n+    # most overloaded first\n+    assert [m[\"name\"] for m in r[\"mechanics\"]] == [\"Dev\", \"Ravi\", \"Priya\"]\n+\n+\n+def test_workload_week_boundaries(client):\n+    _set_jobs(client, JOBS)\n+    for day in [\"2026-11-23\", \"2026-11-28\", \"2026-11-29\", \"today\"]:  # Mon, Sat, the Sunday after, today (Mon)\n+        r = client.get(f\"/api/reports/workload/{day}\").json()\n+        assert (r[\"week_start\"], r[\"week_end\"]) == (\"2026-11-23\", \"2026-11-28\"), day\n+    # Sunday 2026-11-22 is the end of the week before\n+    r = client.get(\"/api/reports/workload/2026-11-22\").json()\n+    assert (r[\"week_start\"], r[\"week_end\"]) == (\"2026-11-16\", \"2026-11-21\")\n+    by_name = {m[\"name\"]: m for m in r[\"mechanics\"]}\n+    assert by_name[\"Ravi\"][\"workload_hours\"] == 4 and by_name[\"Dev\"][\"workload_hours\"] == 0\n+\n+\n+def test_workload_bad_date(client):\n+    for day in [\"2026-13-01\", \"next-week\"]:\n+        resp = client.get(f\"/api/reports/workload/{day}\")\n+        assert resp.status_code == 200\n+        body = resp.json()\n+        assert body[\"ok\"] is False and body[\"error\"]\n",
